"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["78009"],{76726(a){a.exports=JSON.parse('{"id":"F454","slug":"fund-performance-metrics","name":"Private Fund Metrics: IRR, MOIC, TVPI, DPI, RVPI","subject":"Alternative Investments","section":"Alternatives","topic":"Fund performance metrics: IRR, MOIC, TVPI, DPI","level":"Intermediate","aliases":["TVPI","DPI","RVPI","MOIC","PME","net IRR"],"formula":{"latex":"DPI=\\\\frac{\\\\sum D}{\\\\sum P},\\\\quad RVPI=\\\\frac{NAV}{\\\\sum P},\\\\quad TVPI=DPI+RVPI,\\\\quad 0=\\\\sum_{t}\\\\frac{D_{t}-P_{t}+NAV_{T}\\\\mathbb{1}_{t=T}}{(1+IRR)^{t}}","also":[],"text":"DPI = total distributions / total paid-in capital (cash actually returned); RVPI = remaining net asset value / paid-in capital (value still held); TVPI = DPI + RVPI (total value per unit paid in, also called the net multiple); IRR = rate that sets the net present value of calls, distributions and final NAV to zero"},"symbols":[{"symbol":"P_t","meaning":"Capital called in year t","unit":"money"},{"symbol":"D_t","meaning":"Distributions in year t","unit":"money"},{"symbol":"NAV","meaning":"Reported value of the investor\'s remaining stake","unit":"money"}],"when_to_use":"Use it to read a private fund report. TVPI shows total value created but part of it is only a valuation, so DPI is the part already in your hands. IRR depends on timing and can look high early on; a multiple (MOIC, TVPI) ignores time. Read all three together and be careful comparing a fund with unrealized value to a finished one.","worked_example":{"problem":"A fund called 30, 30, 20 and 10 in years 0 to 3. It paid back 10 in year 2, 10 in year 3, 25 in year 4 and 40 in year 5, and the remaining stake is valued at 45.","inputs":{"c":[30,30,20,10,0,0],"d":[0,0,10,10,25,40],"nav":45},"steps":[{"label":"Paid-in capital","working":null,"value":"90.00"},{"label":"DPI = distributions / paid-in","working":null,"value":"0.94"},{"label":"RVPI = NAV / paid-in","working":"45 / 90","value":"0.50"},{"label":"TVPI = DPI + RVPI","working":"0.944444+0.5","value":"1.44"},{"label":"Net flows with NAV added to the last year","working":null,"value":"-30.00, -30.00, -10.00, 0.00, 25.00, 40.00"},{"label":"Net IRR","working":null,"value":"11.7%"}],"answer":"Paid-in capital is 90.00. DPI is 0.94, RVPI is 0.50 and TVPI is 1.44. The net IRR, counting the remaining value as received in the last year, is 11.7%. Only 0.94 of every 1 paid in has come back as cash so far."},"calculator":{"available":true,"inputs":[{"id":"c","label":"Capital called per year (years 0, 1, 2, ...)","unit":"money","type":"list","default":[30,30,20,10,0,0],"hint":""},{"id":"d","label":"Distributions per year","unit":"money","type":"list","default":[0,0,10,10,25,40],"hint":""},{"id":"nav","label":"Remaining net asset value at the end","unit":"money","type":"number","default":45,"hint":""}],"checks":[{"expr":"count(c)==count(d) and sum(c)>0","message":"Enter the same number of years for calls and distributions, with some capital called."}],"steps":[{"id":"paid","label":"Paid-in capital","expr":"sum(c)","format":"num2"},{"id":"dpi","label":"DPI = distributions / paid-in","expr":"sum(d)/paid","format":"num2"},{"id":"rvpi","label":"RVPI = NAV / paid-in","expr":"nav/paid","format":"num2"},{"id":"tvpi","label":"TVPI = DPI + RVPI","expr":"dpi+rvpi","format":"num2"},{"id":"fl","label":"Net flows with NAV added to the last year","expr":"minus(d, c)","format":"list2"},{"id":"netirr","label":"Net IRR","expr":"irr(addlast(fl, nav))","format":"pct1"}],"results":["paid","dpi","rvpi","tvpi","netirr"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"paid":90,"dpi":0.9444444444444444,"rvpi":0.5,"tvpi":1.4444444444444444,"netirr":0.1172915707054469}},"finder":{"finds":"How much a private fund has returned and what it is worth in total","needs":"Calls, distributions by year, remaining value"},"related":[{"slug":"irr","name":"Internal Rate of Return (IRR)"},{"slug":"j-curve-cumulative-cash","name":"J-Curve: Cumulative Net Cash Flow of a Fund"},{"slug":"buyout-value-creation","name":"Buyout Returns and Value Creation Bridge"}],"related_ids":["F029","F453","F451"],"group":"Modern finance and practice","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>D</mi><mi>P</mi><mi>I</mi><mo>=</mo><mfrac><mrow><mo>\u2211</mo><mi>D</mi></mrow><mrow><mo>\u2211</mo><mi>P</mi></mrow></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>R</mi><mi>V</mi><mi>P</mi><mi>I</mi><mo>=</mo><mfrac><mrow><mi>N</mi><mi>A</mi><mi>V</mi></mrow><mrow><mo>\u2211</mo><mi>P</mi></mrow></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>T</mi><mi>V</mi><mi>P</mi><mi>I</mi><mo>=</mo><mi>D</mi><mi>P</mi><mi>I</mi><mo>+</mo><mi>R</mi><mi>V</mi><mi>P</mi><mi>I</mi><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mn>0</mn><mo>=</mo><munder><mo>\u2211</mo><mi>t</mi></munder><mfrac><mrow><msub><mi>D</mi><mi>t</mi></msub><mo>\u2212</mo><msub><mi>P</mi><mi>t</mi></msub><mo>+</mo><mi>N</mi><mi>A</mi><msub><mi>V</mi><mi>T</mi></msub><msub><mn mathvariant=\\"double-struck\\">1</mn><mrow><mi>t</mi><mo>=</mo><mi>T</mi></mrow></msub></mrow><mrow><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><mi>I</mi><mi>R</mi><mi>R</mi><msup><mo stretchy=\\"false\\">)</mo><mi>t</mi></msup></mrow></mfrac></mrow><annotation encoding=\\"application/x-tex\\">DPI=\\\\frac{\\\\sum D}{\\\\sum P},\\\\quad RVPI=\\\\frac{NAV}{\\\\sum P},\\\\quad TVPI=DPI+RVPI,\\\\quad 0=\\\\sum_{t}\\\\frac{D_{t}-P_{t}+NAV_{T}\\\\mathbb{1}_{t=T}}{(1+IRR)^{t}}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"pe-carry-waterfall","name":"Private Equity Distribution Waterfall and Carry"},"next":{"slug":"normal-probability","name":"Probability from a Normal Distribution"},"lesson":null,"total":522}')}}]);